float insidecircle(vec2 vec, vec2 circle, float radius)
{
    float ds  = abs(distance(vec, circle) - radius);
    if (ds <= 0.01){
        return ds;
    }else{
        return -1.0;
    }
}

vec2 getnorm(vec2 pos, vec2 circle){
    return normalize(pos-circle);
}

vec3 lightcalc(vec2 pos, vec2 circle, float radius, vec2 lightpos)
{

    if(insidecircle(pos, circle, radius) < 0.0){
        //not on edge
        return vec3(0.0);

    }else{
        //we're on edge of circle
        vec2 norm = getnorm(pos, circle);
        float diffuse = dot(normalize(lightpos-pos), norm);
        return vec3(diffuse);
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.y;
    uv *= 2.;
    uv -= 1.;

    vec2 mousepos = 2.*(iMouse.xy/iResolution.y) - 1.;
    vec2 lightpos = vec2(mousepos.x, mousepos.y);


    vec3 color = lightcalc(uv.xy, vec2(1.,0.), 0.5, lightpos);
    // Output to screen
    fragColor = vec4(color,1.0);
}
